%[text] Constants
fns = ["redmark.png" "red2.png"] %[output:185bc396]
pxl400s = [836,1261;212 610] %[output:9fc3a2fc]
%%
%[text] Handle
ifn = 2 %[output:32db23d2]
fn = fns(ifn);
pxl400 = pxl400s(ifn,:);
%%
imshow(rm) %[output:0e2f7d62]
xline(pxl400) %[output:0e2f7d62]
%%
%[text] Loop
rm = imread(fn);
pxl400 = pxl400s(ifn,:);
imshow(rm) %[output:84995742]
xline(pxl400) %[output:84995742]
rcut = rm(:,:,1)>200&rm(:,:,2)<30&rm(:,:,3)<30;
imshow(rcut) %[output:9b5d831f]
cc = bwconncomp(rcut) %[output:2482354a]
centroid = regionprops(cc,'Centroid') %[output:754ec89a]
pxltoE = [-400 400;1 1]*inv([pxl400;1 1]) %[output:4c79ed2b]
ct = reshape([centroid.Centroid],2,[]);
xs = sort(ct(1,:));
spam = pxltoE*[xs ; ones(size(xs))];
epos = sort(spam(1,:)) %[output:305edd91]
%%
